insert into public.places (id, slug, name, group_id, category_id, region_id, address, phone, website, menu_url, image_url, image_source_url, image_attribution, image_checked_at, logo_url, logo_source_url, logo_checked_at, place_type, source_url, source_checked_at, map_url, data_notes, latitude, longitude, features, tags, service_details, is_active) values ('thrashers-garsfontein', 'thrashers-garsfontein', 'Thrashers Padel & Skate', null, 'sport_outdoors', 'garsfontein', '241 Serene Street, Garsfontein, Pretoria, 0081', '063 758 1694', 'https://thrashers.co.za/', null, null, null, null, null, null, null, null, 'sports_centre', 'https://thrashers.co.za/', '2026-10-17', 'https://goo.gl/maps/ENsdXZFGkM3geLVx6', 'Published hours apply to the venue; court availability and lessons require a booking check. The skate page states helmets are compulsory for under-18s. Coordinates use the venue''s linked Google place pin, not the map camera centre.', -25.7890875, 28.285009, '{}'::text[], array['Padel', 'Skateboarding', 'BMX', 'Rollerblading']::text[], '{"coordinate_precision":"operator_linked_place_pin","coordinate_source":"https://thrashers.co.za/","hours_scope":"venue","activities": ["padel","skateboarding","bmx","rollerblading"],"booking_url":"https://thrashers.co.za/padel/","fees_url":"https://thrashers.co.za/fees/","contact_email":"info@thrashers.co.za","skate_requirement":"Helmets compulsory for under-18s","activity_source":"https://thrashers.co.za/skate/"}'::jsonb, false) on conflict (id) do update set slug = excluded.slug, name = excluded.name, group_id = excluded.group_id, category_id = excluded.category_id, region_id = excluded.region_id, address = excluded.address, phone = coalesce(excluded.phone, places.phone), website = excluded.website, menu_url = coalesce(excluded.menu_url, places.menu_url), image_url = coalesce(excluded.image_url, places.image_url), image_source_url = coalesce(excluded.image_source_url, places.image_source_url), image_attribution = coalesce(excluded.image_attribution, places.image_attribution), image_checked_at = coalesce(excluded.image_checked_at, places.image_checked_at), logo_url = coalesce(excluded.logo_url, places.logo_url), logo_source_url = coalesce(excluded.logo_source_url, places.logo_source_url), logo_checked_at = coalesce(excluded.logo_checked_at, places.logo_checked_at), place_type = excluded.place_type, source_url = excluded.source_url, source_checked_at = excluded.source_checked_at, map_url = excluded.map_url, data_notes = excluded.data_notes, latitude = excluded.latitude, longitude = excluded.longitude, features = excluded.features, tags = excluded.tags, service_details = excluded.service_details, updated_at = now();
insert into public.places (id, slug, name, group_id, category_id, region_id, address, phone, website, menu_url, image_url, image_source_url, image_attribution, image_checked_at, logo_url, logo_source_url, logo_checked_at, place_type, source_url, source_checked_at, map_url, data_notes, latitude, longitude, features, tags, service_details, is_active) values ('create-wolwespruit', 'create-wolwespruit', 'Create Wolwespruit', 'create-ceramics', 'entertainment', 'erasmuskloof', '501 Jochemus Street, Wolwespruit, Erasmuskloof, Pretoria, 0048', null, 'https://www.createwolwespruit.co.za/', null, null, null, null, null, null, null, null, 'pottery_painting_studio', 'https://www.createwolwespruit.co.za/', '2026-10-17', 'https://www.google.com/maps/dir/?api=1&destination=-25.8100821%2C28.263422', 'Contact number 066 221 8622 is WhatsApp only, so it is not stored as a call number. Daily hours are 09:00-17:00; paint nights have separate dates and times. The pin marks the Wolwespruit site''s published directions destination, not the studio doorway. One inline email link points to Red Barn despite showing the Wolwespruit email; the footer confirms the Wolwespruit address.', -25.8100821, 28.263422, array['family_friendly']::text[], array['Ceramic painting', 'Art', 'Family activities', 'Cafe']::text[], '{"site":"Wolwespruit MTB and Trail Park","coordinate_precision":"shared_site_directions_destination","coordinate_source":"https://wolwespruit.co.za/scripts.8138b9f4dcb5a4639c62.js","hours_scope":"studio_daily_hours","activities": ["ceramic_painting"],"booking_url":"https://www.createwolwespruit.co.za/bookings/","whatsapp_only":"066 221 8622","whatsapp_url":"https://wa.me/27662218622","contact_email":"info@createwolwespruit.co.za","menu_page":"https://www.createwolwespruit.co.za/menus/"}'::jsonb, false) on conflict (id) do update set slug = excluded.slug, name = excluded.name, group_id = excluded.group_id, category_id = excluded.category_id, region_id = excluded.region_id, address = excluded.address, phone = coalesce(excluded.phone, places.phone), website = excluded.website, menu_url = coalesce(excluded.menu_url, places.menu_url), image_url = coalesce(excluded.image_url, places.image_url), image_source_url = coalesce(excluded.image_source_url, places.image_source_url), image_attribution = coalesce(excluded.image_attribution, places.image_attribution), image_checked_at = coalesce(excluded.image_checked_at, places.image_checked_at), logo_url = coalesce(excluded.logo_url, places.logo_url), logo_source_url = coalesce(excluded.logo_source_url, places.logo_source_url), logo_checked_at = coalesce(excluded.logo_checked_at, places.logo_checked_at), place_type = excluded.place_type, source_url = excluded.source_url, source_checked_at = excluded.source_checked_at, map_url = excluded.map_url, data_notes = excluded.data_notes, latitude = excluded.latitude, longitude = excluded.longitude, features = excluded.features, tags = excluded.tags, service_details = excluded.service_details, updated_at = now();
